import{_ as i,a,c as e,ac as t}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"Go gRPC 实践：协议生成、调用边界与调试","description":"统一 protoc 插件、Go 包路径和 grpcui 调试，按请求超时与状态码验证 RPC。","frontmatter":{"title":"Go gRPC 实践：协议生成、调用边界与调试","description":"统一 protoc 插件、Go 包路径和 grpcui 调试，按请求超时与状态码验证 RPC。","sources":[{"repository":"jekyall_blog","file":"_posts/Language/golang/Micro service framework/2015-10-12-gRPC.md","date":"Thu Dec 26 2019 14:22:12 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"go","title":"Go","link":"/topics/go/"},{"id":"grpc","title":"RPC 与 gRPC","link":"/topics/grpc/"},{"id":"protobuf","title":"序列化与 Protobuf","link":"/topics/protobuf/"}],"kind":"开发实践","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Go 工程实践","summary":"统一 protoc 插件、Go 包路径和 grpcui 调试，按请求超时与状态码验证 RPC。","status":"active","related":[{"title":"Go 编码规范：格式、命名、接口与评审","link":"/programming/go/plus/practice/coding_guidelines","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 标准库：文件、JSON 与时间","link":"/programming/go/plus/stdlib/stdlib","kind":"知识专题","scope":"general","audience":"general"},{"title":"Go 反射：检查类型、字段与可修改性","link":"/programming/go/base/advanced/reflection","kind":"知识专题","scope":"general","audience":"general"},{"title":"Go 分配与 GC：逃逸、引用保留和内存预算","link":"/programming/go/base/advanced/gc","kind":"知识专题","scope":"general","audience":"general"},{"title":"Go 工具链：环境、构建、测试与命令速查","link":"/programming/go/toolchain","kind":"排错","scope":"general","audience":"general"}],"prev":{"text":"Go 接口文档：swag 生成与版本管理","link":"/programming/go/plus/ecosystem/swagger"},"next":false},"hashRedirects":{"grpc":"/programming/go/plus/ecosystem/grpc#tools","安装-protoc-工具":"/programming/go/plus/ecosystem/grpc#tools","下载工具依赖":"/programming/go/plus/ecosystem/grpc#tools","创建-protoc-文件":"/programming/go/plus/ecosystem/grpc#tools","grpc-基础":"/programming/go/plus/ecosystem/grpc#tools"},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Go 接口文档：swag 生成与版本管理","link":"/programming/go/plus/ecosystem/swagger"},"next":false},"headers":[],"relativePath":"programming/go/plus/ecosystem/grpc.md","filePath":"programming/go/plus/ecosystem/grpc.md"}'),p={name:"programming/go/plus/ecosystem/grpc.md"};function l(n,s,r,h,o,k){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="go-grpc-实践-协议生成、调用边界与调试" tabindex="-1">Go gRPC 实践：协议生成、调用边界与调试 <a class="header-anchor" href="#go-grpc-实践-协议生成、调用边界与调试" aria-label="Permalink to &quot;Go gRPC 实践：协议生成、调用边界与调试&quot;">​</a></h1><blockquote><p>本轮只做理论正文与源码静态复核；下列命令、示例和测试均未执行。已有输出按代码推演或历史记录理解，不作为本轮运行证据。</p></blockquote><p><span id="grpc"></span><span id="安装-protoc-工具"></span><span id="下载工具依赖"></span><span id="创建-protoc-文件"></span><span id="grpc-基础"></span></p><p>前置：<a href="/principles/protocols/protobuf/protocol-buffer">Protobuf 基础</a>、<a href="/programming/go/plus/ecosystem/go.mod">Modules</a>、<a href="/programming/go/base/intermediate/engineering#goroutine">context</a>。先完成单机客户端与服务端，再引入注册发现和框架。</p><h2 id="tools" tabindex="-1">工具与版本 <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;工具与版本 {#tools}&quot;">​</a></h2><p>需要 protoc、protoc-gen-go、protoc-gen-go-grpc。先确定相互兼容的 Go、生成器和运行时库版本，并记录在工程工具说明里。以下为安装命令形式，执行时将版本占位符替换为项目选定值：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> google.golang.org/protobuf/cmd/protoc-gen-go@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> google.golang.org/grpc/cmd/protoc-gen-go-grpc@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protoc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protoc-gen-go</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protoc-gen-go-grpc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>确认 GOBIN 或 GOPATH/bin 在 PATH 中；protoc 本身不是通过 go install 安装的 Go 工具。</p><h2 id="generate" tabindex="-1">生成消息和服务 <a class="header-anchor" href="#generate" aria-label="Permalink to &quot;生成消息和服务 {#generate}&quot;">​</a></h2><p>使用<a href="/principles/protocols/protobuf/protocol-buffer#proto3">协议课的 hello.proto</a>，模块名为 <code>example.com/hello</code>，在模块根运行：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protoc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --go_out=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --go_opt=paths=source_relative</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --go-grpc_out=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --go-grpc_opt=paths=source_relative</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api/hello.proto</span></span></code></pre></div><p>预期生成 <code>api/hello.pb.go</code> 和 <code>api/hello_grpc.pb.go</code>。<code>-I</code> 是 proto 导入搜索根，<code>paths=source_relative</code> 控制输出路径；Go 导入路径由 go_package 等选项决定。旧的 <code>--go_out=plugins=grpc</code> 属于旧生成链路，不应与两个新插件的命令混用。</p><p>若提示无法确定 Go import path，检查 go_package 是否完整，与 go.mod 及目标目录是否一致；提示找不到插件时检查 PATH；依赖 .proto 找不到时检查 -I，不应直接修改生成文件或把临时本机路径写成团队公共配置。</p><h2 id="rpc-lifecycle" tabindex="-1">服务端与客户端 <a class="header-anchor" href="#rpc-lifecycle" aria-label="Permalink to &quot;服务端与客户端 {#rpc-lifecycle}&quot;">​</a></h2><p>服务端创建 listener 与 grpc.Server，注册生成的 GreeterServer 实现。生成接口若要求嵌入 UnimplementedGreeterServer，应按当前生成代码的要求实现；旧文章中的极简 server 不能直接跨版本照搬。客户端复用连接，调用时传入带 deadline 的 context，并检查返回状态。</p><p>服务方法的形状如下，这是依赖生成代码的实现片段：</p><div class="language-go vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">s </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SayHello</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">req</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hellopb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HelloRequest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hellopb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HelloReply</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> req.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, status.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(codes.InvalidArgument, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;name is required&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hellopb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">HelloReply</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{Message: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello &quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> req.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">GetName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()}, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">nil</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>其中 hellopb 是生成包，status/codes 来自 google.golang.org/grpc。网络连接成功、服务注册成功与某次调用成功是不同阶段，错误应分别定位；生产通信的传输凭据与身份校验由服务部署方案决定。可运行的完整双端工程与连接 API 以 <a href="https://grpc.io/docs/languages/go/quickstart/" target="_blank" rel="noopener noreferrer">gRPC Go 官方快速开始</a> 为基准。</p><h2 id="grpcui" tabindex="-1">grpcui 与描述符 <a class="header-anchor" href="#grpcui" aria-label="Permalink to &quot;grpcui 与描述符 {#grpcui}&quot;">​</a></h2><p>命令行工具同样用显式版本的 go install 安装，例如 <code>github.com/fullstorydev/grpcui/cmd/grpcui@&lt;version&gt;</code>。若服务没有开放 reflection，可用 protoc 生成包含依赖的描述符集：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protoc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --descriptor_set_out=api.protoset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include_imports</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api/hello.proto</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grpcui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -bind</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8506</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -plaintext</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -protoset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api.protoset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:50051</span></span></code></pre></div><p><code>-plaintext</code> 适用于本地明文练习，与生产 TLS 配置分开。不要把 0.0.0.0 当成客户端必须连接的服务地址。</p><h2 id="exercise" tabindex="-1">练习与验收 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习与验收 {#exercise}&quot;">​</a></h2><p>本页是协议生成与接入参考，代码块为需要补充生成包及已选依赖的片段，不宣称完整双端工程。先在纸面核对同一模块的协议与生成路径，再推演正常姓名、空姓名、服务未启动和 deadline 四种结果。若引入服务发现，额外核对注册实例的可达地址、服务名、环境隔离与注销顺序，而不只检查注册页面出现一个实例。</p><h2 id="static-review" tabindex="-1">调用案例与参考判断 <a class="header-anchor" href="#static-review" aria-label="Permalink to &quot;调用案例与参考判断 {#static-review}&quot;">​</a></h2><p>假定SayHello使用上面的实现，name=Alice预期Hello Alice；name为空预期InvalidArgument且没有成功消息。服务不可达与请求期限耗尽不是一个结果：连接/重试策略和剩余deadline共同决定最终状态，不能硬断言“停服务一定立即Unavailable”。客户端应同时检查RPC错误、返回值和context状态。</p><p>提示：服务端正常返回前deadline已耗尽时，能否据客户端错误断言服务端未执行？</p><details><summary>参考答案</summary><p>不能。错误可能发生在执行前、处理中或响应传输阶段；写操作需要独立幂等合同。服务发现只提供候选地址，不保证本次RPC成功。生成路径检查不等于编译、网络或身份验证。</p></details>`,28)])])}const c=i(p,[["render",l]]);export{d as __pageData,c as default};
